private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    try{
        int currentCapacity = buffer.length;
        int newCapacity = Math.max(currentCapacity + size, Math.max(currentCapacity * 2, 16));
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, currentCapacity);
        buffer = newBuffer;
    }catch(NullPointerException e){
        // If the underlying buffer is null, initialize it with required capacity
        buffer = new byte[Math.max(size, 16)];
    }catch(OutOfMemoryError e){
        // Propagate the error after logging, if desired
        throw e;
    }
}

