public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("target and resultMap must not be null");
    }
    try {
        Set<V> leftSet = new HashSet<>();
        Set<V> rightSet = new HashSet<>();

        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            V vertex = entry.getValue();
            if (vertex == null) {
                continue;
            }
            // add vertex to the graph
            if (!target.containsVertex(vertex)) {
                target.addVertex(vertex);
            }
            // simple heuristic to partition vertices into two sets:
            // keys starting with an uppercase letter go to the left set,
            // otherwise to the right set
            if (key != null && !key.isEmpty() && Character.isUpperCase(key.charAt(0))) {
                leftSet.add(vertex);
            } else {
                rightSet.add(vertex);
            }
        }

        // add edges between every pair of vertices from left and right sets
        for (V left : leftSet) {
            for (V right : rightSet) {
                // avoid self‑loops and duplicate edges
                if (!left.equals(right) && target.getEdge(left, right) == null) {
                    target.addEdge(left, right);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

protected int findByte(byte value, int pos) {
    // If the buffer is not initialized, we cannot search
    if (buffer == null) {
        return -1;
    }

    // Validate the starting position
    if (pos < 0 || pos >= buffer.length) {
        return -1;
    }

    // Scan forward until we find the byte or reach the end of the buffer
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }

    // Byte not found
    return -1;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) throw new NullPointerException("OutputStream cannot be null");
    if (message == null) throw new NullPointerException("Message cannot be null");
    if (schema == null) throw new NullPointerException("Schema cannot be null");
    if (buffer == null) throw new NullPointerException("Buffer cannot be null");

    // Reset the buffer and serialize the message into it
    buffer.reset(); // assume LinkedBuffer has reset() to clear its state
    schema.writeTo(buffer, message);
    int size = buffer.getPosition(); // number of bytes written

    // Write the length prefix as a Varint32
    int temp = size;
    while ((temp & ~0x7F) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp & 0x7F);

    // Write the serialized message bytes
    byte[] data = buffer.getItemBuffer(); // assume this returns the underlying byte array
    out.write(data, 0, size);

    // Clear buffer for next use
    buffer.clear(); // assume LinkedBuffer has a clear() method

    return size;
}

