public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type raw = pType.getRawType();
    if (!(raw instanceof Class)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) raw;
    if (!rawClass.isAssignableFrom(targetType)) {
        return null;
    }
    Type[] typeArgs = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        Type t = typeArgs[i];
        if (t instanceof Class) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type rawT = ((ParameterizedType) t).getRawType();
            if (rawT instanceof Class) {
                result[i] = (Class<?>) rawT;
            } else {
                return null;
            }
        } else {
            // TypeVariable, WildcardType, etc., cannot be resolved to a concrete Class
            return null;
        }
    }
    return result;
}

@Override public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    // Attempt to merge with an existing entry if available
    // Assume the METRICS type provides a unique key via getKey()
    Object key = data.getKey();
    METRICS existing = cache.get(key);
    if (existing != null) {
        // Try to merge using a conventionally named merge or combine method
        try {
            java.lang.reflect.Method mergeMethod = data.getClass()
                .getMethod("merge", data.getClass());
            mergeMethod.invoke(existing, data);
            cache.put(key, existing);
        } catch (Exception e) {
            // If merging is not supported, replace the entry
            cache.put(key, data);
        }
    } else {
        cache.put(key, data);
    }
}

void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("Target bucket cannot be null");
    }
    // Handle the case where this bucket is the head (previous == null)
    Bucket prev = this.prev;
    Bucket next = this;
    // Link the new bucket
    bucket.prev = prev;
    bucket.next = next;
    // Update the surrounding buckets
    if (prev != null) {
        prev.next = bucket;
    }
    // this bucket becomes the next after the inserted bucket
    this.prev = bucket;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name must not be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("Mappings must not be null");
    }
    try {
        // Retrieve the current mappings for the index from Elasticsearch
        GetMappingsRequest request = new GetMappingsRequest();
        request.indices(tableName);
        GetMappingsResponse response = client.indices().getMapping(request, RequestOptions.DEFAULT);
        Map<String, MappingMetaData> currentIndices = response.mappings();
        MappingMetaData currentMeta = currentIndices.get(tableName);
        if (currentMeta == null) {
            return new Mappings(); // nothing to diff
        }

        // Current index properties (excluding _source)
        Map<String, Object> currentProps = new HashMap<>(currentMeta.getSourceAsMap());
        currentProps.remove("_source");

        // Input mapping properties
        Map<String, Object> inputProps = mappings.getSourceAsMap();

        // Build diff: fields present in current but missing in input
        Mappings diff = new Mappings();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            if (!inputProps.containsKey(field)) {
                diff.put(field, entry.getValue());
            }
        }
        return diff;
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute diff structure", e);
    }
}

