protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive");
    }
    if (start > end) {
        throw new IllegalArgumentException("start must not be greater than end");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    if (day <= 0) {
        throw new IllegalArgumentException("day part of timeBucket must be positive");
    }
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    // Ensure newDay does not exceed month length for safety; clamp to 31 if necessary
    if (newDay > 31) {
        newDay = 31;
    }
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("Index or length out of bounds");
    }
    int utfSize = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        char c = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(c) && i + 1 < end) {
            char c2 = str.charAt(i + 1);
            if (Character.isLowSurrogate(c2)) {
                codePoint = Character.toCodePoint(c, c2);
                i++; // skip low surrogate
            } else {
                codePoint = c;
            }
        } else {
            codePoint = c;
        }
        if (codePoint <= 0x7F) {
            utfSize += 1;
        } else if (codePoint <= 0x7FF) {
            utfSize += 2;
        } else if (codePoint <= 0xFFFF) {
            utfSize += 3;
        } else {
            utfSize += 4;
        }
        i++;
    }
    return utfSize;
}

