private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) return;
    int i = 0;
    final int len = descriptor.length();
    // For method descriptors, skip the '(' and parse arguments until ')'
    if (descriptor.charAt(0) == '('){
        i = 1; // start after '('
        while (i < len && descriptor.charAt(i) != ')'){
            i = consumeAndPopType(descriptor, i);
        }
        // skip the ')'
        if (i < len && descriptor.charAt(i) == ')') i++;
    }else{
        // type descriptor
        i = consumeAndPopType(descriptor, i);
    }
}

/* Helper to consume a type descriptor starting at 'index' and pop an abstract
 * type from the output stack if it is a reference type.
 * Returns the index after the consumed type. */
private int consumeAndPopType(String desc, int index){
    char c = desc.charAt(index);
    if (c == '['){
        // Skip all array brackets
        while (index < desc.length() && desc.charAt(index) == '['){
            index++;
        }
        // Skip the component type
        if (index < desc.length()){
            if (desc.charAt(index) == 'L'){
                // Object type inside the array
                while (index < desc.length() && desc.charAt(index) != ';'){
                    index++;
                }
                // Skip the ';'
                if (index < desc.length() && desc.charAt(index) == ';') index++;
            }else{
                // Primitive component type
                index++;
            }
        }
        // An array type is a reference type, pop it
        output.pop();
    }else if (c == 'L'){
        // Object type
        index++; // skip 'L'
        while (index < desc.length() && desc.charAt(index) != ';'){
            index++;
        }
        // Skip ';'
        if (index < desc.length() && desc.charAt(index) == ';') index++;
        output.pop();
    }else{
        // Primitive type – nothing to pop
        index++;
    }
    return index;
}

