            String key = entry.getKey();
            JsonElement val = entry.getValue();
            if(val == null){
                continue;
            }
            if("ats".equals(key)){
                // If present, set 'ats' explicitly as string
                result.put("ats", val.getAsString());
                continue;
            }
            if(val.isJsonPrimitive()){
                JsonPrimitive prim = val.getAsJsonPrimitive();
                if(prim.isBoolean()){
                    result.put(key, prim.getAsBoolean());
                }else if(prim.isNumber()){
                    result.put(key, prim.getAsNumber());
                }else if(prim.isString()){
                    result.put(key, prim.getAsString());
                }else{
                    result.put(key, prim.getAsString());
                }
            }else if(val.isJsonArray()){
                result.put(key, val.getAsJsonArray());
            }else if(val.isJsonObject()){
                result.put(key, val.getAsJsonObject());
            }else{
