                        continue;
                    } else {
                        // unrecognized escape, keep the char as is
                        sb.append(next);
                    }
                    break;
            }
            i++; // skip escape character
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset) {
    if (charset == null) {
