    try {
        // Attempt to get the canonical Java charset name
        return java.nio.charset.Charset.forName(charset).name();
    } catch (IllegalArgumentException e) {
        // Fallback to a manual mapping for common MIME names
        String lower = charset.toLowerCase(java.util.Locale.ROOT);
        switch (lower) {
            case "utf-8":
            case "utf8":
                return "UTF-8";
            case "us-ascii":
            case "usascii":
                return "US-ASCII";
            case "iso-8859-1":
            case "iso88591":
                return "ISO-8859-1";
            case "windows-1252":
            case "windows1252":
                return "windows-1252";
            default:
                // Return null if the charset cannot be resolved
                return null;
        }
    }
}

