protected int removeUnusedNodes() {
    int removed = 0;
    try {
        if (root == null) {
            return 0;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category node = stack.pop();
            java.util.List<Category> children = node.getChildren();
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception ignored) {
        // Swallow any unexpected exceptions during pruning
    }
    return removed;
}

