final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    int cpCount = classFileBuffer.getShort(6);
    if (constantPoolEntryIndex >= cpCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }
    int offset = 8;
    int currentIndex = 1;
    while (currentIndex < constantPoolEntryIndex) {
        byte tag = classFileBuffer.get(offset);
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = classFileBuffer.getShort(offset);
                offset += 2 + len;
                break;
            case 3:
            case 4:
            case 9:
            case 10:
            case 11:
            case 12:
            case 15:
            case 16:
            case 18:
                offset += 4;
                break;
            case 5:
            case 6: // LONG or DOUBLE occupy two entries
                offset += 8;
                currentIndex++; // account for the second slot
                break;
            default:
                throw new IllegalArgumentException("Unsupported constant pool tag: " + tag);
        }
        currentIndex++;
    }
    int utfSize = classFileBuffer.getShort(offset + 1);
    if (charBuffer.length < utfSize) {
        throw new IllegalArgumentException("charBuffer too small to hold UTF8 bytes");
    }
    byte[] bytes = new byte[utfSize];
    ByteBuffer dup = classFileBuffer.asReadOnlyBuffer();
    dup.position(offset + 3);
    dup.get(bytes);
    String str = new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    if (str.length() > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer too small for decoded string");
    }
    str.getChars(0, str.length(), charBuffer, 0);
    return str;
}

