public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative");
    }
    if (byteLength == 0) {
        return this;
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength) {
            throw new IndexOutOfBoundsException(
                "byteOffset and byteLength exceed byteArrayValue bounds");
        }
    }
    // Ensure internal buffer has enough capacity
    int requiredCapacity = this.position + byteLength;
    if (requiredCapacity > this.buffer.length) {
        int newCap = Math.max(this.buffer.length * 2, requiredCapacity);
        byte[] newBuffer = new byte[newCap];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.position);
        this.buffer = newBuffer;
    }
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.position, byteLength);
    } else {
        java.util.Arrays.fill(this.buffer, this.position, this.position + byteLength, (byte) 0);
    }
    this.position += byteLength;
    return this;
}

