protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, 0.0, Collections.emptyList());
    }
    // Build adjacency mapping from vertices to incident edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Pick a start vertex (source of first edge)
    Iterator<E> it = tour.iterator();
    E firstEdge = it.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = startVertex;
    List<E> orderedEdges = new ArrayList<>(tour.size());
    Set<E> remaining = new HashSet<>(tour);
    double totalWeight = 0.0;
    while (!remaining.isEmpty()) {
        List<E> edgesAtCurrent = adjacency.get(currentVertex);
        if (edgesAtCurrent == null) {
            throw new IllegalArgumentException("Graph is not connected or tour is invalid");
        }
        boolean found = false;
        for (E e : edgesAtCurrent) {
            if (!remaining.contains(e)) continue;
            // Append this edge to the path
            orderedEdges.add(e);
            remaining.remove(e);
            totalWeight += graph.getEdgeWeight(e);
            // Move to the adjacent vertex
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            currentVertex = src.equals(currentVertex) ? tgt : src;
            found = true;
            break;
        }
        if (!found) {
            throw new IllegalArgumentException("Cannot traverse remaining edges; tour may be disconnected");
        }
    }
    V endVertex = currentVertex;
    return new GraphWalk<>(graph, startVertex, endVertex, totalWeight, orderedEdges);
}

