    if (bucketsByLabel == null || labels == null) return;
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) return;
    Set<Integer> src = bucketsByLabel.get(minLabel);
    if (src == null || src.isEmpty()) return;
    // ensure destination bucket exists
    Set<Integer> dst = null;
    if (!bucketsByLabel.isEmpty()) {
        dst = bucketsByLabel.get(0);
    }
    if (dst == null) {
        dst = new HashSet<>();
        if (bucketsByLabel.isEmpty()) {
            bucketsByLabel.add(dst);
        } else {
            bucketsByLabel.set(0, dst);
        }
    }
    for (Integer v : src) {
        dst.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }
    src.clear();
}

