private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return Pair.of(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    long totalSum = 0L;
    for (int val : bounds){
        totalSum += (long) val;
    }
    List<Integer> suffixSumList = new ArrayList<>(n);
    long suffixSum = 0L;
    for (int i = n - 1; i >= 0; i--){
        suffixSum += (long) bounds.get(i);
        // keep the sum within int bounds, as the list is specified to hold Integer
        suffixSumList.add(0, (int) suffixSum);
    }
    return Pair.of(suffixSumList, totalSum);
}

