public ByteVector putInt(final int intValue){
    // Ensure there is enough space for 4 more bytes
    if (used + 4 > buffer.length) {
        int newSize = Math.max(used + 4, buffer.length * 2);
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(buffer, 0, newBuffer, 0, used);
        buffer = newBuffer;
    }
    // Store the int in big-endian order
    buffer[used++] = (byte)(intValue >> 24);
    buffer[used++] = (byte)(intValue >> 16);
    buffer[used++] = (byte)(intValue >> 8);
    buffer[used++] = (byte)(intValue);
    return this;
}

