private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // empty or single vertex is trivially a clique
    }
    // Convert to list for indexed access
    ArrayList<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys == null ? 0 : keys.size());
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }

    int minVal = Integer.MAX_VALUE;
    for (K key : keys) {
        if (key instanceof Integer) {
            int v = (Integer) key;
            if (v < minVal) {
                minVal = v;
            }
        }
    }

    if (minVal == Integer.MAX_VALUE) {
        // No integer keys found; return an empty bounds list
        return bounds;
    }

    for (int i = 0; i < keys.size(); i++) {
        bounds.add(minVal);
    }
    return bounds;
}

private void pop(final String descriptor) {
    // If the descriptor is a method descriptor, strip the parentheses to leave only the argument types.
    int start = 0;
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '(') {
        int endIdx = descriptor.indexOf(')', 1);
        if (endIdx == -1) {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        descriptor = descriptor.substring(1, endIdx);
        start = 0;
    }
    int i = start;
    while (i < descriptor.length()) {
        char ch = descriptor.charAt(i);
        // Skip array dimensions.
        if (ch == '[') {
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) break;
            ch = descriptor.charAt(i);
        }
        // Skip reference types up to the terminating ';'.
        if (ch == 'L') {
            while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                i++;
            }
            // Move past the ';'.
            i++;
            // Pop the reference type entry.
            popAbstractType();
            continue;
        }
        // For primitive types: B, C, D, F, I, J, S, Z, V
        switch (ch) {
            case 'B':
            case 'C':
            case 'D':
            case 'F':
            case 'I':
            case 'J':
            case 'S':
            case 'Z':
            case 'V':
                popAbstractType();
                break;
            default:
                // Unknown descriptor part, skip to avoid infinite loop.
                break;
        }
        i++;
    }
}

