public int readTag() throws IOException {
    if (content == null) {
        throw new IOException("No content buffer available");
    }
    int tag = 0;
    int shift = 0;
    while (shift < 32) {
        if (!content.hasRemaining()) {
            // Reached EOF while expecting a tag
            return 0;
        }
        byte b = content.get();
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint tag");
}

